<div class="page-heading"><div><p class="eyebrow">SHOP ADMINISTRATION</p><h1>Branding &amp; workflow settings</h1><p class="text-secondary">Tabler remains local. The shop chooses how equipment is pulled and returned.</p></div><a href="/users" data-workspace class="btn">Manage users &amp; roles</a></div>
<form action="/settings" method="post" enctype="multipart/form-data" data-ajax-form><?= csrf() ?>
<section class="card floating-card" data-card-key="branding"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">palette</span>Shop identity</h2><div class="card-body"><div class="form-grid">
<label class="form-label">Shop name<input class="form-control mb-3" name="brand_name" value="<?= e($settings['brand_name'] ?? 'Theatre Shop') ?>" maxlength="160" required></label><label class="form-label">Default appearance<select class="form-select mb-3" name="theme_default"><?php foreach (['light','dark','system'] as $theme): ?><option value="<?= $theme ?>" <?= ($settings['theme_default'] ?? 'dark')===$theme?'selected':'' ?>><?= ucfirst($theme) ?></option><?php endforeach; ?></select></label></div>
<div class="form-grid"><?php foreach (App\Controllers\SettingsController::BRANDING as $key): ?><label class="form-label"><?= e(ucwords(str_replace('_',' ',$key))) ?><input class="form-control" type="file" name="<?= e($key) ?>" accept=".png,.jpg,.jpeg,.webp"><?php if (!empty($settings[$key])): ?><img class="branding-preview mt-2" src="/branding/<?= e($key) ?>" alt="<?= e($key) ?> preview"><?php endif; ?></label><?php endforeach; ?></div><p class="text-secondary mt-3">Separate dark/light logos and backgrounds. PNG, JPEG or WebP only; 10 MB and 6000 x 6000 maximum. Use PNG for the favicon. SVG and executable uploads are intentionally blocked.</p></div></section>
<section class="card floating-card" data-card-key="workflow-settings"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">barcode_reader</span>Shop workflows</h2><div class="card-body form-grid"><?php foreach (['pull_mode'=>'Pull operations','return_mode'=>'Return operations'] as $key=>$label): ?><label class="form-label"><?= e($label) ?><select class="form-select" name="<?= e($key) ?>"><option value="barcode" <?= ($settings[$key] ?? 'barcode')==='barcode'?'selected':'' ?>>Barcode scanner (preferred)</option><option value="manual" <?= ($settings[$key] ?? '')==='manual'?'selected':'' ?>>Manual quantity entry</option></select></label><?php endforeach; ?></div></section>
<div class="form-error" role="alert" hidden></div><button class="btn btn-primary">Save shop settings</button></form>
